        down)
            opts=""
            choices=""
            names=0 ;;
        edit)
            opts=""
            choices=""
            names=1 ;;
        failover)
            opts="--clear"
            choices=""
            names=1 ;;
        fav)
            opts=""
            choices=""
            names=1 ;;
        get)
            opts=""
            choices=""
            names=0 ;;
        group)
            opts="--ask-password"
            choices="list edit"
            names=0 ;;
        gui)
            opts="--background"
            choices=""
            names=0 ;;
        history)
            opts="-n --lines --json --clear"
            choices=""
            names=0 ;;
        import)
            opts="--name --protocol --user --password --ask-password --stunnel --stunnel-sni --stunnel-ca --stunnel-verify"
            choices=""
