            names=0 ;;
        logs)
            opts="-f --follow -n --lines"
            choices=""
            names=0 ;;
        ls)
            opts="--latency -l --names --sort --json"
            choices=""
            names=0 ;;
        menu)
            opts=""
            choices=""
            names=0 ;;
        netproxy)
            opts="--user --ask-password --json"
            choices="status on off set clear ignore apps dns udp"
            names=0 ;;
        networks)
            opts=""
